import {validSessions,results,statistics,summary,within,localDate,money,HANDS} from './domain.js';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const colors=['#fbbf24','#06b6d4','#818cf8','#d1829b','#a855f7','#c58f60','#66c4bc','#c4c86b','#d17365'];
export function chartData(state,{type,players=[],from='',to=''}){const all=validSessions(state).sort((a,b)=>a.startedAt.localeCompare(b.startedAt)||a.id.localeCompare(b.id)),sessions=all.filter(s=>within(s,from,to)),ps=state.players.filter(p=>!players.length||players.includes(p.id));let labels=[],series=[],currency=!['rebuys','participation','hands'].includes(type);
 if(['cumulative','net','rebuys'].includes(type)){labels=sessions.map(s=>s.name+' · '+localDate(s.startedAt));series=ps.map((p,i)=>{let accumulated=all.filter(s=>from&&localDate(s.startedAt)<from).reduce((a,s)=>a+(results(s).find(r=>r.playerId===p.id)?.net||0),0);return {name:p.name,color:colors[i%colors.length],values:sessions.map(s=>{const r=results(s).find(r=>r.playerId===p.id);if(type==='cumulative'){accumulated+=r?.net||0;return accumulated;}return type==='net'?r?.net??null:r?.rebuys??null;})};});}
 else if(type==='comparison'){labels=ps.map(p=>p.name);const stats=statistics(state,sessions);series=[{name:'Resultado no período',color:colors[0],values:ps.map(p=>stats.find(x=>x.id===p.id).net)}];}
 else if(type==='monthly'||type==='participation'){labels=[...new Set(sessions.map(s=>localDate(s.startedAt).slice(0,7)))];series=ps.map((p,i)=>({name:p.name,color:colors[i%colors.length],values:labels.map(m=>sessions.filter(s=>localDate(s.startedAt).startsWith(m)&&s.participants.some(x=>x.playerId===p.id)).reduce((a,s)=>a+(type==='monthly'?results(s).find(r=>r.playerId===p.id).net:1),0))}));}
 else{labels=HANDS;series=ps.map((p,i)=>({name:p.name,color:colors[i%colors.length],values:HANDS.map(h=>sessions.flatMap(s=>s.rounds.filter(r=>!r.deleted&&r.hand===h&&r.winners.includes(p.id))).length)}));}
 return {labels,series,currency,sessions:sessions.length};
}
export function renderChart(target,dataTarget,state,options,onPoint){const data=chartData(state,options);if(!data.sessions||!data.labels.length||!data.series.length){target.innerHTML='<div class="empty"><span class="symbol">↗</span><h3>Ainda não há dados neste recorte</h3><p>Finalize uma sessão ou ajuste os filtros para explorar a evolução.</p></div>';dataTarget.innerHTML='';return;}const {labels,series,currency}=data,values=series.flatMap(s=>s.values).filter(v=>v!==null),min=Math.min(0,...values),max=Math.max(1,...values),w=850,h=340,left=75,top=25,right=25,bottom=55,range=max-min||1,x=i=>left+(labels.length===1?(w-left-right)/2:i*(w-left-right)/(labels.length-1)),y=v=>top+(max-v)/range*(h-top-bottom);let svg='<svg viewBox="0 0 '+w+' '+h+'" role="img" aria-label="Gráfico dos registros filtrados">';for(let i=0;i<=4;i++){const v=min+range*i/4,yy=y(v);svg+='<line class="grid" x1="'+left+'" x2="'+(w-right)+'" y1="'+yy+'" y2="'+yy+'"/><text text-anchor="end" x="'+(left-10)+'" y="'+(yy+4)+'">'+esc(currency?money(Math.round(v)):Math.round(v))+'</text>';}labels.forEach((l,i)=>{if(i%Math.max(1,Math.ceil(labels.length/7))===0)svg+='<text x="'+x(i)+'" y="'+(h-20)+'" text-anchor="middle">'+esc(l.length>15?l.slice(0,13)+'…':l)+'</text>';});series.forEach((s,si)=>{const pts=s.values.map((v,i)=>v===null?null:[x(i),y(v)]);let segments=[],seg=[];for(const pt of pts){if(pt)seg.push(pt);else{if(seg.length)segments.push(seg);seg=[];}}if(seg.length)segments.push(seg);segments.forEach(seg=>{svg+='<polyline fill="none" stroke="'+s.color+'" stroke-width="2.5" points="'+seg.map(p=>p.join(',')).join(' ')+'"/>';});pts.forEach((p,i)=>{if(p)svg+='<circle tabindex="0" data-series="'+si+'" data-index="'+i+'" cx="'+p[0]+'" cy="'+p[1]+'" r="5" stroke="#121520" stroke-width="2" fill="'+s.color+'"><title>'+esc(s.name+' · '+labels[i]+': '+(currency?money(s.values[i]):s.values[i]))+'</title></circle>';});});svg+='</svg>';target.innerHTML='<div class="chart">'+svg+'</div><div class="chart-legend">'+series.map(s=>'<span><i style="background:'+s.color+'"></i>'+esc(s.name)+'</span>').join('')+'</div>';target.querySelectorAll('circle').forEach(c=>{const fn=()=>{const s=series[c.dataset.series],i=Number(c.dataset.index);onPoint(s.name+' · '+labels[i]+': '+(currency?money(s.values[i]):s.values[i]));};c.onclick=fn;c.onfocus=fn;c.onmouseenter=fn;});dataTarget.innerHTML='<details><summary>Consultar valores em tabela</summary><div class="table-wrap"><table><thead><tr><th>Registro</th>'+series.map(s=>'<th>'+esc(s.name)+'</th>').join('')+'</tr></thead><tbody>'+labels.map((l,i)=>'<tr><td>'+esc(l)+'</td>'+series.map(s=>'<td>'+ (s.values[i]===null?'Não participou':currency?money(s.values[i]):s.values[i])+'</td>').join('')+'</tr>').join('')+'</tbody></table></div></details><p class="help">'+(options.type==='cumulative'?'Acumulado histórico: o saldo anterior ao início do filtro é preservado.':options.type==='hands'?'Distribuição por vencedor registrado; uma rodada dividida pode aparecer para mais de um jogador.':'Valores restritos ao período selecionado.')+'</p>';}
export async function exportRetro(state,sessions,{format='vertical',money:showMoney=true,photos=false,period='Toda a história',selected=[0,1,2,3]}={}){const c=document.createElement('canvas');c.width=1080;c.height=format==='square'?1080:1350;const ctx=c.getContext('2d'),sum=summary(state,sessions),h=c.height;const bg=ctx.createLinearGradient(0,0,1080,h);bg.addColorStop(0,'#1e1b4b');bg.addColorStop(.5,'#121520');bg.addColorStop(1,'#0a0b10');ctx.fillStyle=bg;ctx.fillRect(0,0,1080,h);ctx.strokeStyle='#6366f1';ctx.lineWidth=2;ctx.strokeRect(28,28,1024,h-56);ctx.strokeStyle='#6366f133';ctx.strokeRect(40,40,1000,h-80);ctx.fillStyle='#fbbf24';ctx.textAlign='center';ctx.font='75px Georgia';ctx.fillText('♣',540,130);ctx.font='45px Georgia';ctx.fillText('A POKERZADA LENDÁRIA',540,200);ctx.fillStyle='#f8fafc';ctx.font='26px sans-serif';ctx.fillText('RETROSPECTIVA DA TROPA',540,251);ctx.fillStyle='#94a3b8';ctx.font='22px sans-serif';ctx.fillText(period,540,292);ctx.fillStyle='#cbd5e1';ctx.font='22px sans-serif';ctx.fillText(sum.games+' noites  ·  '+sum.people+' pessoas  ·  '+sum.rounds+' rodadas',540,345);
 const names=ps=>ps.length?ps.map(p=>p.name).join(' & '):'Sem registro',items=[['REI DA MESA',names(sum.kings),showMoney&&sum.kings.length?money(sum.kings[0].net)+' de lucro acumulado':'Maior lucro positivo do período',sum.kings],['PRESENÇA LENDÁRIA',names(sum.presence),sum.presence.length?sum.presence[0].games+' participações':'Nenhuma participação',sum.presence],['MAIOR VIRADA',names(sum.bestNight),showMoney&&sum.bestNight.length?money(sum.bestNight[0].best)+' em uma noite':'Maior lucro individual em uma noite',sum.bestNight],['A MÃO DO PERÍODO',sum.commonHands.map(c=>c.hand).join(' & ')||'Não registrada','Somente rodadas documentadas',[]],['MAIOR PREJUÍZO',names(sum.losses),showMoney&&sum.losses.length?money(sum.losses[0].net)+' acumulados':'Menor resultado líquido do período',sum.losses],['MAIS RE-BUYS',names(sum.rebuyLeaders),sum.rebuyLeaders.length?sum.rebuyLeaders[0].rebuys+' registros':'Sem registros',sum.rebuyLeaders]].filter((_,i)=>selected.includes(i));
 const cellH=format==='square'?270:330;for(let i=0;i<items.length;i++){const [label,name,note,ps]=items[i],x=75+(i%2)*475,y=395+Math.floor(i/2)*cellH;ctx.fillStyle='#ffffff05';ctx.fillRect(x,y,455,cellH-22);ctx.strokeStyle='#fbbf2444';ctx.strokeRect(x,y,455,cellH-22);ctx.textAlign='center';ctx.fillStyle='#fbbf24';ctx.font='17px sans-serif';ctx.fillText(label,x+227,y+39);let nameY=y+88;if(photos&&ps[0]?.avatar){try{const img=await loadImage(ps[0].avatar);ctx.save();ctx.beginPath();ctx.arc(x+227,y+90,32,0,2*Math.PI);ctx.clip();ctx.drawImage(img,x+195,y+58,64,64);ctx.restore();nameY=y+155;}catch{}}ctx.fillStyle='#f8fafc';ctx.font='30px Georgia';wrap(ctx,name,x+227,nameY,400,35,2);ctx.fillStyle='#94a3b8';ctx.font='16px sans-serif';wrap(ctx,note,x+227,y+cellH-55,410,23,2);}
 ctx.fillStyle='#94a3b8';ctx.font='19px sans-serif';ctx.textAlign='center';ctx.fillText('O jogo é presencial. A resenha é eterna.',540,h-83);ctx.font='14px sans-serif';ctx.fillText('Resultados de sessões finalizadas e conferidas',540,h-55);return c.toDataURL('image/png');}
function wrap(ctx,text,x,y,width,line,max){const words=text.split(' ');let row='',rows=[];for(const word of words){if(ctx.measureText(row+' '+word).width>width&&row){rows.push(row);row=word;}else row+=(row?' ':'')+word;}rows.push(row);rows.slice(0,max).forEach((r,i)=>ctx.fillText(i===max-1&&rows.length>max?r+'…':r,x,y+i*line));}
const loadImage=src=>new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=src;});


